let halShader
function setup() {
	createCanvas(600, 600, WEBGL)
	halShader = createShader(vert, frag)
}

function draw() {
	background(0)

	rotateY(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2)/windowWidth * PI * 0.25)
	rotateX(-((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2)/windowHeight * PI * 0.25)

	translate(0, 0, -100)

	ambientLight(100)
	const lightColor = color('#333333')
	for (const side of [-1, 1]) {
		pointLight(50, 50, 50, side * width/2, -height*0.8, 1200)
		pointLight(20, 20, 20, side * width/2, -height*0.8, 2000)
	}

	noStroke()
	push()
		specularMaterial(190)
		rotateX(PI/2)
		shininess(50)
		cylinder(width * 0.3, 20, 36, 2)
		shininess(70)
		cylinder(width * 0.28, 36, 36, 2)
		shininess(100)
		cylinder(width * 0.27, 42, 36, 2)
	pop()

	push()
		shader(halShader)
		sphere(width * 0.25, 36, 36)
	pop()
}
